const toggle=document.querySelector('.menu-toggle');const nav=document.querySelector('#primary-nav');toggle?.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'ปิดเมนู':'เปิดเมนู')});nav?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');toggle?.setAttribute('aria-expanded','false')}));
const video=document.querySelector('#hero-video');const videoToggle=document.querySelector('#video-toggle');videoToggle?.addEventListener('click',()=>{if(video.paused){video.play().catch(()=>{});videoToggle.textContent='Ⅱ';videoToggle.setAttribute('aria-label','หยุดวิดีโอ');videoToggle.setAttribute('aria-pressed','false')}else{video.pause();videoToggle.textContent='▶';videoToggle.setAttribute('aria-label','เล่นวิดีโอ');videoToggle.setAttribute('aria-pressed','true')}});
document.querySelectorAll('[data-news-tab]').forEach(tab=>tab.addEventListener('click',()=>{const selected=tab.dataset.newsTab;document.querySelectorAll('[data-news-tab]').forEach(item=>{const active=item===tab;item.classList.toggle('active',active);item.setAttribute('aria-selected',String(active))});document.querySelectorAll('[data-news-panel]').forEach(panel=>{panel.hidden=panel.dataset.newsPanel!==selected})}));
